<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway;

use Override;
use ArrayIterator;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\UserGroupMembership;

/**
 * @template-extends ArrayIterator<int, UserGroupMembership>
 */
class UserGroupMembershipSlide extends \ArrayIterator
{
    private readonly ?UserGroupMembership $last;
    private readonly UserGroupMembershipCursor $nextCursor;
    public function __construct(
        private readonly ?\Closure $next,
        private readonly ?UserGroupMembershipCursor $cursor,
        private readonly array $values
    ) {
        parent::__construct($values);
        $this->last = $values ? end($values) : null;
        $cursor = $this->cursor ?? new UserGroupMembershipCursor(limit: 1000);
        $this->nextCursor = null === $this->last ? $cursor : $cursor->next($this->last, null);
    }
    public function cursor(): ?UserGroupMembershipCursor
    {
        return $this->cursor;
    }
    public function nextCursor(): UserGroupMembershipCursor
    {
        return $this->nextCursor;
    }
    public function values(): array
    {
        return $this->values;
    }
    #[Override]
    public function current(): ?UserGroupMembership
    {
        return parent::current();
    }
    public function map(\Closure $fn): UserGroupMembershipSlide
    {
        return new UserGroupMembershipSlide($this->next, $this->cursor, array_map($fn, $this->values));
    }
    public function slide(\Closure $fn): UserGroupMembershipSlide
    {
        $collected = array_values(array_filter($this->values, $fn));
        $cursor = $this->cursor;
        if (null !== $cursor && null !== $this->next) {
            $limit = $cursor->limit();
            $current = $this;
            while (count($collected) < $limit && count($current->values) >= $limit) {
                $current = ($this->next)($current, $current->nextCursor);
                $collected = array_merge($collected, array_values(array_filter($current->values, $fn)));
            }
            $collected = array_slice($collected, 0, $limit);
        }
        return new UserGroupMembershipSlide($this->next, $cursor, $collected);
    }
}
